workers = [
    asyncio.ensure_future(worker())
    for _ in range(min(max_concurrent, len(task_list)))
]

try:
    # ``shield`` so that a cancellation of *this* coroutine does not reach
    # the workers directly: we cancel them exactly once ourselves and then
    # wait for their cleanup to finish.
    waiter = asyncio.gather(*workers, return_exceptions=True)
    try:
        await asyncio.shield(waiter)
    except (asyncio.CancelledError, KeyboardInterrupt):
        for w in workers:
            w.cancel()
        await _wait_uninterruptible(workers)
        if not waiter.done():  # pragma: no cover - defensive
            waiter.cancel()
        waiter.exception() if waiter.done() and not waiter.cancelled() else None
        if interrupted:
            if self_task is not None:
                uncancel = getattr(self_task, "uncancel", None)
                if uncancel is not None:
                    uncancel()
            raise KeyboardInterrupt from None
        raise
finally:

